class Solution {
    public boolean canCross(int[] stones) {
        java.util.Map<Integer, java.util.Set<Integer>> jumpsByPosition = new java.util.HashMap<>();
        for (int stone : stones) {
            jumpsByPosition.put(stone, new java.util.HashSet<>());
        }
        jumpsByPosition.get(0).add(0);
        int target = stones[stones.length - 1];
        for (int stone : stones) {
            for (int lastJump : jumpsByPosition.get(stone)) {
                for (int nextJump = lastJump - 1; nextJump <= lastJump + 1; nextJump++) {
                    if (nextJump <= 0) {
                        continue;
                    }
                    int nextPosition = stone + nextJump;
                    java.util.Set<Integer> nextJumps = jumpsByPosition.get(nextPosition);
                    if (nextJumps == null) {
                        continue;
                    }
                    if (nextPosition == target) {
                        return true;
                    }
                    nextJumps.add(nextJump);
                }
            }
        }
        return false;
    }
}

class Solution {
    public boolean canCross(int[] stones) {
        int n = stones.length;
        boolean[][] dp = new boolean[n][n + 1];
        dp[0][0] = true;
        for (int i = 1; i < n; i++) {
            for (int j = 0; j < i; j++) {
                int jump = stones[i] - stones[j];
                if (jump > n) {
                    continue;
                }
                boolean reachable = dp[j][jump];
                if (jump > 0) {
                    reachable = reachable || dp[j][jump - 1];
                }
                if (jump + 1 <= n) {
                    reachable = reachable || dp[j][jump + 1];
                }
                if (reachable) {
                    dp[i][jump] = true;
                    if (i == n - 1) {
                        return true;
                    }
                }
            }
        }
        return false;
    }
}

class Solution {
    private int[] stones;
    private java.util.Map<Integer, Integer> indexByPosition;
    private Boolean[][] memo;

    public boolean canCross(int[] stones) {
        this.stones = stones;
        int n = stones.length;
        indexByPosition = new java.util.HashMap<>();
        for (int i = 0; i < n; i++) {
            indexByPosition.put(stones[i], i);
        }
        memo = new Boolean[n][n + 1];
        return dfs(0, 0);
    }

    private boolean dfs(int index, int lastJump) {
        if (index == stones.length - 1) {
            return true;
        }
        if (lastJump <= stones.length && memo[index][lastJump] != null) {
            return memo[index][lastJump];
        }
        for (int nextJump = lastJump - 1; nextJump <= lastJump + 1; nextJump++) {
            if (nextJump <= 0) {
                continue;
            }
            Integer nextIndex = indexByPosition.get(stones[index] + nextJump);
            if (nextIndex != null && dfs(nextIndex, nextJump)) {
                if (lastJump <= stones.length) {
                    memo[index][lastJump] = true;
                }
                return true;
            }
        }
        if (lastJump <= stones.length) {
            memo[index][lastJump] = false;
        }
        return false;
    }
}

class Solution {
    public boolean canCross(int[] stones) {
        int n = stones.length;
        java.util.Map<Integer, Integer> indexByPosition = new java.util.HashMap<>();
        for (int i = 0; i < n; i++) {
            indexByPosition.put(stones[i], i);
        }
        boolean[][] visited = new boolean[n][n + 1];
        java.util.ArrayDeque<int[]> queue = new java.util.ArrayDeque<>();
        queue.add(new int[] {0, 0});
        visited[0][0] = true;
        while (!queue.isEmpty()) {
            int[] state = queue.removeFirst();
            int index = state[0];
            int lastJump = state[1];
            for (int nextJump = lastJump - 1; nextJump <= lastJump + 1; nextJump++) {
                if (nextJump <= 0 || nextJump > n) {
                    continue;
                }
                Integer nextIndex = indexByPosition.get(stones[index] + nextJump);
                if (nextIndex == null || visited[nextIndex][nextJump]) {
                    continue;
                }
                if (nextIndex == n - 1) {
                    return true;
                }
                visited[nextIndex][nextJump] = true;
                queue.addLast(new int[] {nextIndex, nextJump});
            }
        }
        return false;
    }
}

class Solution {
    public boolean canCross(int[] stones) {
        int n = stones.length;
        java.util.Map<Integer, Integer> indexByPosition = new java.util.HashMap<>();
        for (int i = 0; i < n; i++) {
            indexByPosition.put(stones[i], i);
        }
        java.util.BitSet[] reachable = new java.util.BitSet[n];
        for (int i = 0; i < n; i++) {
            reachable[i] = new java.util.BitSet(n + 1);
        }
        reachable[0].set(0);
        for (int i = 0; i < n; i++) {
            for (int lastJump = reachable[i].nextSetBit(0); lastJump >= 0; lastJump = reachable[i].nextSetBit(lastJump + 1)) {
                for (int nextJump = lastJump - 1; nextJump <= lastJump + 1; nextJump++) {
                    if (nextJump <= 0 || nextJump > n) {
                        continue;
                    }
                    Integer nextIndex = indexByPosition.get(stones[i] + nextJump);
                    if (nextIndex == null) {
                        continue;
                    }
                    if (nextIndex == n - 1) {
                        return true;
                    }
                    reachable[nextIndex].set(nextJump);
                }
            }
        }
        return false;
    }
}
